import 'package:flutter/material.dart';
import 'package:flutter_hbb/dolphin/about.dart';
import 'package:flutter_hbb/dolphin/brand.dart';
import 'package:flutter_hbb/dolphin/digits.dart';
import 'package:flutter_hbb/dolphin/tech_ui/header.dart';
import 'package:flutter_test/flutter_test.dart';

import 'contrast.dart';

// Owner 2026-11-13: the technician app shows its name with «کارشناس»; the customer app keeps «دلفین کانکت». brand.dart
// is generated by dolphin/gen_profile.py (settings.json variants.technician.display-name-fa).
void main() {
  test('the technician name is the product name with «کارشناس»', () {
    expect(DolphinBrand.nameFa, 'دلفین کانکت');
    expect(DolphinBrand.technicianNameFa, 'دلفین کانکت کارشناس');
    // This build's name is one of the two (the checks generate the customer variant).
    expect([DolphinBrand.nameFa, DolphinBrand.technicianNameFa], contains(DolphinBrand.appNameFa));
  });

  testWidgets('the technician header says «دلفین کانکت کارشناس» once, without a second «کارشناس»', (tester) async {
    tester.view.physicalSize = const Size(2400, 600);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.reset);
    final search = TextEditingController();
    final idField = TextEditingController();
    final focus = FocusNode();
    addTearDown(search.dispose);
    addTearDown(idField.dispose);
    addTearDown(focus.dispose);
    await tester.pumpWidget(lightApp(TechHeader(
        myId: '287654321',
        staffName: 'علی رضایی',
        search: search,
        searchFocus: focus,
        onSearch: (_) {},
        idField: idField,
        onConnect: () {},
        onDemo: () {},
        onBell: () {},
        themeMode: ThemeMode.light,
        onThemeMode: (_) {},
        onSettings: () {},
        onCopyId: () {},
        onSignOut: () {})));
    expect(find.text('دلفین کانکت کارشناس'), findsOneWidget);
    expect(find.text('کارشناس'), findsNothing);
    expect(find.text('دلفین کانکت'), findsNothing);
    expectAllTextReadable(tester);
  });

  testWidgets('About heads with this build\'s name and its version', (tester) async {
    await tester.pumpWidget(lightApp(const DolphinAboutHeading()));
    expect(find.text(DolphinBrand.appNameFa), findsOneWidget);
    expect(find.text(versionLabel(DolphinBrand.version)), findsOneWidget);
    await tester.pumpWidget(lightApp(const DolphinAboutHeading(name: 'دلفین کانکت کارشناس', version: '2.1.0')));
    expect(find.text('دلفین کانکت کارشناس'), findsOneWidget);
    expect(find.text('نسخه‌ی ۲.۱.۰'), findsOneWidget);
  });
}
